    ItemCard(english: "She has a bad cough and sore throat.", translations: {"ar": "عندها كحة شديدة والتهاب في الحلق", "de": "Sie hat einen schlimmen Husten und Halsschmerzen", "es": "Tiene una tos fuerte y dolor de garganta", "fr": "Elle a une mauvaise toux et un mal de gorge", "it": "Ha una brutta tosse e mal di gola", "ru": "У нее сильный кашель и боль в горле", "zh": "她咳嗽得很厉害，喉咙痛", "tr": "Şiddetli öksürüğü ve boğaz ağrısı var"}),
    ItemCard(english: "Eating too much sugar can lead to diabetes.", translations: {"ar": "أكل السكر كتير ممكن يؤدي للسكري", "de": "Zu viel Zucker kann zu Diabetes führen", "es": "Comer demasiada azúcar puede provocar diabetes", "fr": "Manger trop de sucre peut conduire au diabète", "it": "Mangiare troppo zucchero può portare al diabete", "ru": "Употребление слишком большого количества сахара может привести к диабету", "zh": "吃太多糖会导致糖尿病", "tr": "Çok fazla şeker yemek diyabete yol açabilir"}),
    ItemCard(english: "He was diagnosed with leukemia at a young age.", translations: {"ar": "تم تشخيصه بسرطان الدم في سن مبكرة", "de": "Bei ihm wurde in jungen Jahren Leukämie diagnostiziert", "es": "Fue diagnosticado con leucemia a una edad temprana", "fr": "Il a reçu un diagnostic de leucémie à un jeune âge", "it": "Gli è stata diagnosticata la leucemia in giovane età", "ru": "У него диагностировали лейкемию в молодом возрасте", "zh": "他年轻时被诊断出患有白血病", "tr": "Genç yaşta lösemi teşhisi kondu"}),
    ItemCard(english: "Obesity is a growing problem worldwide.", translations: {"ar": "السمنة مشكلة بتزيد في العالم كله", "de": "Fettleibigkeit ist ein wachsendes Problem weltweit", "es": "La obesidad es un problema creciente en todo el mundo", "fr": "L'obésité est un problème croissant dans le monde", "it": "L'obesità è un problema crescente in tutto il mondo", "ru": "Ожирение - растущая проблема во всем мире", "zh": "肥胖是全球日益严重的问题", "tr": "Obezite dünya çapında büyüyen bir sorundur"}),
    ItemCard(english: "Migraine can cause severe throbbing pain.", translations: {"ar": "الصداع النصفي ممكن يسبب ألم شديد نابض", "de": "Migräne kann starke pochende Schmerzen verursachen", "es": "La migraña puede causar un dolor punzante intenso", "fr": "La migraine peut causer une douleur lancinante sévère", "it": "L'emicrania può causare un forte dolore pulsante", "ru": "Мигрень может вызывать сильную пульсирующую боль", "zh": "偏头痛会引起剧烈的搏动性疼痛", "tr": "Migren şiddetli zonklayıcı ağrıya neden olabilir"}),
    ItemCard(english: "Pneumonia is a serious lung infection.", translations: {"ar": "الالتهاب الرئوي هو عدوى رئوية خطيرة", "de": "Lungenentzündung ist eine ernsthafte Lungeninfektion", "es": "La neumonía es una infección pulmonar grave", "fr": "La pneumonie est une infection pulmonaire grave", "it": "La polmonite è una grave infezione polmonare", "ru": "Пневмония - это серьезная легочная инфекция", "zh": "肺炎是一种严重的肺部感染", "tr": "Zatürre ciddi bir akciğer enfeksiyonudur"}),
    ItemCard(english: "He suffered a stroke last month.", translations: {"ar": "هو أصيب بجلطة الشهر اللي فات", "de": "Er erlitt letzten Monat einen Schlaganfall", "es": "Sufrió un derrame cerebral el mes pasado", "fr": "Il a fait un accident vasculaire cérébral le mois dernier", "it": "Ha avuto un ictus il mese scorso", "ru": "У него случился инсульт в прошлом месяце", "zh": "他上月中风了", "tr": "Geçen ay felç geçirdi"}),
    ItemCard(english: "Malnutrition affects millions of children.", translations: {"ar": "سوء التغذية بيأثر على ملايين الأطفال", "de": "Unterernährung betrifft Millionen von Kindern", "es": "La desnutrición afecta a millones de niños", "fr": "La malnutrition affecte des millions d'enfants", "it": "La malnutrizione colpisce milioni di bambini", "ru": "Недоедание затрагивает миллионы детей", "zh": "营养不良影响着数百万儿童", "tr": "Yetersiz beslenme milyonlarca çocuğu etkiliyor"}),
    ItemCard(english: "Tonsillitis causes pain when swallowing.", translations: {"ar": "التهاب اللوز بيسبب ألم عند البلع", "de": "Mandelentzündung verursacht Schmerzen beim Schlucken", "es": "La amigdalitis causa dolor al tragar", "fr": "L'amygdalite provoque des douleurs à la déglutition", "it": "La tonsillite causa dolore durante la deglutizione", "ru": "Тонзиллит вызывает боль при глотании", "zh": "扁桃体炎导致吞咽时疼痛", "tr": "Bademcik iltihabı yutkunma sırasında ağrıya neden olur"}),
    ItemCard(english: "Gallstones can be very painful.", translations: {"ar": "حصوات المرارة ممكن تكون مؤلمة جدا", "de": "Gallensteine können sehr schmerzhaft sein", "es": "Los cálculos biliares pueden ser muy dolorosos", "fr": "Les calculs biliaires peuvent être très douloureux", "it": "I calcoli biliari possono essere molto dolorosi", "ru": "Желчные камни могут быть очень болезненными", "zh": "胆结石可能非常痛苦", "tr": "Safra taşları çok ağrılı olabilir"}),
    ItemCard(english: "Anxiety disorder affects daily life.", translations: {"ar": "اضطراب القلق بيأثر على الحياة اليومية", "de": "Angststörung beeinträchtigt das tägliche Leben", "es": "El trastorno de ansiedad afecta la vida diaria", "fr": "Le trouble anxieux affecte la vie quotidienne", "it": "Il disturbo d'ansia influisce sulla vita quotidiana", "ru": "Тревожное расстройство влияет на повседневную жизнь", "zh": "焦虑症影响日常生活", "tr": "Anksiyete bozukluğu günlük yaşamı etkiler"}),
    ItemCard(english: "Chemotherapy is used to treat cancer.", translations: {"ar": "العلاج الكيماوي بيستخدم لعلاج السرطان", "de": "Chemotherapie wird zur Behandlung von Krebs eingesetzt", "es": "La quimioterapia se usa para tratar el cáncer", "fr": "La chimiothérapie est utilisée pour traiter le cancer", "it": "La chemioterapia è usata per curare il cancro", "ru": "Химиотерапия используется для лечения рака", "zh": "化疗用于治疗癌症", "tr": "Kemoterapi kanseri tedavi etmek için kullanılır"}),
    ItemCard(english: "She has a chronic skin condition.", translations: {"ar": "عندها حالة جلدية مزمنة", "de": "Sie hat eine chronische Hauterkrankung", "es": "Tiene una condición crónica de la piel", "fr": "Elle a une affection cutanée chronique", "it": "Ha una condizione cronica della pelle", "ru": "У нее хроническое кожное заболевание", "zh": "她有一种慢性皮肤病", "tr": "Kronik bir cilt rahatsızlığı var"}),
    ItemCard(english: "Vomiting can lead to dehydration.", translations: {"ar": "القيء ممكن يؤدي للجفاف", "de": "Erbrechen kann zu Dehydration führen", "es": "Los vómitos pueden provocar deshidratación", "fr": "Les vomissements peuvent entraîner une déshydratation", "it": "Il vomito può portare alla disidratazione", "ru": "Рвота может привести к обезвоживанию", "zh": "呕吐会导致脱水", "tr": "Kusma dehidrasyona yol açabilir"}),
    ItemCard(english: "He is recovering from pneumonia.", translations: {"ar": "هو بيتعافى من الالتهاب الرئوي", "de": "Er erholt sich von einer Lungenentzündung", "es": "Se está recuperando de neumonía", "fr": "Il se remet d'une pneumonie", "it": "Si sta riprendendo dalla polmonite", "ru": "Он восстанавливается после пневмонии", "zh": "他正在从肺炎中恢复", "tr": "Zatürreden kurtuluyor"}),
    ItemCard(english: "High blood pressure is a silent killer.", translations: {"ar": "ارتفاع ضغط الدم قاتل صامت", "de": "Bluthochdruck ist ein stiller Killer", "es": "La presión arterial alta es un asesino silencioso", "fr": "L'hypertension artérielle est un tueur silencieux", "it": "L'ipertensione è un killer silenzioso", "ru": "Высокое кровяное давление - тихий убийца", "zh": "高血压是无声的杀手", "tr": "Yüksek tansiyon sessiz bir katildir"}),
    ItemCard(english: "The patient is in stable condition.", translations: {"ar": "حالة المريض مستقرة", "de": "Der Zustand des Patienten ist stabil", "es": "El paciente está en condición estable", "fr": "L'état du patient est stable", "it": "Le condizioni del paziente sono stabili", "ru": "Состояние пациента стабильное", "zh": "病人情况稳定", "tr": "Hastanın durumu stabil"}),
    ItemCard(english: "She has a weak immune system.", translations: {"ar": "عندها جهاز مناعي ضعيف", "de": "Sie hat ein schwaches Immunsystem", "es": "Tiene un sistema inmunológico débil", "fr": "Elle a un système immunitaire faible", "it": "Ha un sistema immunitario debole", "ru": "У нее слабая иммунная система", "zh": "她免疫系统较弱", "tr": "Zayıf bir bağışıklık sistemi var"}),
    ItemCard(english: "Regular check-ups help detect diseases early.", translations: {"ar": "الفحوصات المنتظمة بتساعد في اكتشاف الأمراض بدري", "de": "Regelmäßige Untersuchungen helfen, Krankheiten frühzeitig zu erkennen", "es": "Los chequeos regulares ayudan a detectar enfermedades temprano", "fr": "Des contrôles réguliers aident à détecter les maladies tôt", "it": "I controlli regolari aiutano a rilevare le malattie in anticipo", "ru": "Регулярные осмотры помогают выявлять заболевания на ранней стадии", "zh": "定期检查有助于及早发现疾病", "tr": "Düzenli kontroller hastalıkların erken teşhisine yardımcı olur"}),
