    ItemCard(english: "I have known her for a decade.", translations: {"ar": "أنا عارفها من عقد كامل", "de": "Ich kenne sie seit einem Jahrzehnt", "es": "La conozco desde hace una década", "fr": "Je la connais depuis une décennie", "it": "La conosco da un decennio", "ru": "Я знаю ее уже десятилетие", "zh": "我认识她已经十年了", "tr": "Onu on yıldır tanırım"}),
    ItemCard(english: "He never comes late.", translations: {"ar": "هو عمره ما يجي متأخر", "de": "Er kommt nie zu spät", "es": "Nunca llega tarde", "fr": "Il n'arrive jamais en retard", "it": "Non arriva mai in ritardo", "ru": "Он никогда не опаздывает", "zh": "他从不迟到", "tr": "Asla geç kalmaz"}),
    ItemCard(english: "Sometimes I feel tired after work.", translations: {"ar": "أحياناً بحس بتعب بعد الشغل", "de": "Manchmal fühle ich mich nach der Arbeit müde", "es": "A veces me siento cansado después del trabajo", "fr": "Parfois, je me sens fatigué après le travail", "it": "A volte mi sento stanco dopo il lavoro", "ru": "Иногда я чувствую усталость после работы", "zh": "有时候我下班后感到累", "tr": "Bazen işten sonra yorgun hissediyorum"}),
    ItemCard(english: "The sun rises at 6 AM.", translations: {"ar": "الشمس بتشرق الساعة 6 الصبح", "de": "Die Sonne geht um 6 Uhr morgens auf", "es": "El sol sale a las 6 AM", "fr": "Le soleil se lève à 6 heures du matin", "it": "Il sole sorge alle 6 del mattino", "ru": "Солнце встает в 6 утра", "zh": "太阳早上6点升起", "tr": "Güneş sabah 6'da doğar"}),
    ItemCard(english: "We had a meeting last month.", translations: {"ar": "كان عندنا اجتماع الشهر اللي فات", "de": "Wir hatten letzten Monat ein Meeting", "es": "Tuvimos una reunión el mes pasado", "fr": "Nous avons eu une réunion le mois dernier", "it": "Abbiamo avuto una riunione il mese scorso", "ru": "У нас было собрание в прошлом месяце", "zh": "我们上个月开过一次会", "tr": "Geçen ay bir toplantımız vardı"}),
    ItemCard(english: "I will graduate next year.", translations: {"ar": "أنا هتخرج السنة الجاية", "de": "Ich werde nächstes Jahr meinen Abschluss machen", "es": "Me graduaré el próximo año", "fr": "Je vais être diplômé l'année prochaine", "it": "Mi laureerò l'anno prossimo", "ru": "Я закончу учебу в следующем году", "zh": "我明年毕业", "tr": "Gelecek yıl mezun olacağım"}),
    ItemCard(english: "He exercises every day.", translations: {"ar": "هو بتمرن كل يوم", "de": "Er trainiert jeden Tag", "es": "Él hace ejercicio todos los días", "fr": "Il fait de l'exercice tous les jours", "it": "Si allena ogni giorno", "ru": "Он тренируется каждый день", "zh": "他每天都锻炼", "tr": "Her gün egzersiz yapar"}),
    ItemCard(english: "I will travel soon.", translations: {"ar": "أنا هسافر قريباً", "de": "Ich werde bald reisen", "es": "Viajaré pronto", "fr": "Je voyagerai bientôt", "it": "Viaggerò presto", "ru": "Я скоро поеду в путешествие", "zh": "我很快就要去旅行了", "tr": "Yakında seyahat edeceğim"}),
    ItemCard(english: "It's midnight. I should go to sleep.", translations: {"ar": "نص الليل. لازم أنام", "de": "Es ist Mitternacht. Ich sollte schlafen gehen", "es": "Es medianoche. Debería ir a dormir", "fr": "Il est minuit. Je devrais aller dormir", "it": "È mezzanotte. Dovrei andare a dormire", "ru": "Полночь. Мне пора спать", "zh": "午夜了。我应该去睡觉了", "tr": "Gece yarısı. Uyumalıyım"}),
    ItemCard(english: "The birds sing at dawn.", translations: {"ar": "الطيور بتغني في الفجر", "de": "Die Vögel singen im Morgengrauen", "es": "Los pájaros cantan al amanecer", "fr": "Les oiseaux chantent à l'aube", "it": "Gli uccelli cantano all'alba", "ru": "Птицы поют на рассвете", "zh": "鸟儿在黎明时分歌唱", "tr": "Kuşlar şafakta öter"}),
    ItemCard(english: "I sometimes cook dinner for my family.", translations: {"ar": "أنا أحياناً بطبع العشاء لعيلتي", "de": "Ich koche manchmal das Abendessen für meine Familie", "es": "A veces cocino la cena para mi familia", "fr": "Je cuisine parfois le dîner pour ma famille", "it": "A volte cucino la cena per la mia famiglia", "ru": "Иногда я готовлю ужин для своей семьи", "zh": "我有时为家人做晚饭", "tr": "Bazen ailem için akşam yemeği pişiririm"}),
    ItemCard(english: "He rarely eats fast food.", translations: {"ar": "هو نادراً ما بيأكل أكل سريع", "de": "Er isst selten Fast Food", "es": "Él rara vez come comida rápida", "fr": "Il mange rarement de la restauration rapide", "it": "Mangia raramente fast food", "ru": "Он редко ест фастфуд", "zh": "他很少吃快餐", "tr": "Nadiren fast food yer"}),
    ItemCard(english: "We usually have breakfast at 7 AM.", translations: {"ar": "احنا عادة بنفطر الساعة 7 الصبح", "de": "Wir frühstücken normalerweise um 7 Uhr morgens", "es": "Normalmente desayunamos a las 7 AM", "fr": "Nous prenons habituellement le petit-déjeuner à 7 heures", "it": "Di solito facciamo colazione alle 7 del mattino", "ru": "Мы обычно завтракаем в 7 утра", "zh": "我们通常在早上7点吃早餐", "tr": "Genellikle sabah 7'de kahvaltı yaparız"}),
    ItemCard(english: "I will see you in a few minutes.", translations: {"ar": "هشوفك بعد شوية دقايق", "de": "Ich sehe dich in ein paar Minuten", "es": "Te veré en unos minutos", "fr": "Je te verrai dans quelques minutes", "it": "Ti vedrò tra qualche minuto", "ru": "Увидимся через несколько минут", "zh": "几分钟后见", "tr": "Birkaç dakika içinde görüşürüz"}),
    ItemCard(english: "We have a deadline next month.", translations: {"ar": "عندنا موعد نهائي الشهر الجاي", "de": "Wir haben nächsten Monat eine Frist", "es": "Tenemos una fecha límite el próximo mes", "fr": "Nous avons une date limite le mois prochain", "it": "Abbiamo una scadenza il mese prossimo", "ru": "У нас срок в следующем месяце", "zh": "我们下个月有截止日期", "tr": "Gelecek ay bir teslim tarihimiz var"}),
    ItemCard(english: "She always wakes up before sunrise.", translations: {"ar": "هي دايما بتصحى قبل شروق الشمس", "de": "Sie wacht immer vor Sonnenaufgang auf", "es": "Ella siempre se despierta antes del amanecer", "fr": "Elle se réveille toujours avant le lever du soleil", "it": "Si sveglia sempre prima dell'alba", "ru": "Она всегда просыпается до восхода солнца", "zh": "她总是在日出前醒来", "tr": "Her zaman gün doğmadan önce uyanır"}),
    ItemCard(english: "I have never been to Europe.", translations: {"ar": "أنا عمري ما رحت أوروبا", "de": "Ich war noch nie in Europa", "es": "Nunca he estado en Europa", "fr": "Je ne suis jamais allé en Europe", "it": "Non sono mai stato in Europa", "ru": "Я никогда не был в Европе", "zh": "我从未去过欧洲", "tr": "Hiç Avrupa'ya gitmedim"}),
    ItemCard(english: "The concert starts at 8 PM this evening.", translations: {"ar": "الحفلة بتبدأ الساعة 8 المسية", "de": "Das Konzert beginnt heute Abend um 20 Uhr", "es": "El concierto comienza a las 8 PM esta noche", "fr": "Le concert commence à 20 heures ce soir", "it": "Il concerto inizia alle 20 di questa sera", "ru": "Концерт начинается в 8 вечера", "zh": "音乐会今晚8点开始", "tr": "Konser bu akşam saat 20:00'de başlıyor"}),
    ItemCard(english: "We visited our grandparents last week.", translations: {"ar": "احنا زرنا جدودنا الأسبوع اللي فات", "de": "Wir haben letzte Woche unsere Großeltern besucht", "es": "Visitamos a nuestros abuelos la semana pasada", "fr": "Nous avons rendu visite à nos grands-parents la semaine dernière", "it": "Abbiamo visitato i nostri nonni la scorsa settimana", "ru": "Мы навестили наших бабушку и дедушку на прошлой неделе", "zh": "我们上周去看望了祖父母", "tr": "Geçen hafta büyükannelerimizi ziyaret ettik"}),
    ItemCard(english: "I will finish this task soon.", translations: {"ar": "أنا هخلص المهمة دي قريباً", "de": "Ich werde diese Aufgabe bald beenden", "es": "Terminaré esta tarea pronto", "fr": "Je vais bientôt terminer cette tâche", "it": "Finirò presto questo compito", "ru": "Я скоро закончу это задание", "zh": "我很快就会完成这项任务", "tr": "Bu görevi yakında bitireceğim"}),
    ItemCard(english: "He arrived earlier today.", translations: {"ar": "هو وصل النهاردة قبل الوقت", "de": "Er kam heute früher an", "es": "Llegó más temprano hoy", "fr": "Il est arrivé plus tôt aujourd'hui", "it": "È arrivato prima oggi", "ru": "Он прибыл сегодня раньше", "zh": "他今天来早了", "tr": "Bugün daha erken geldi"}),
    ItemCard(english: "We meet every month to discuss progress.", translations: {"ar": "احنا بنتقابل كل شهر عشان نناقش التقدم", "de": "Wir treffen uns jeden Monat, um den Fortschritt zu besprechen", "es": "Nos reunimos cada mes para discutir el progreso", "fr": "Nous nous rencontrons chaque mois pour discuter des progrès", "it": "Ci incontriamo ogni mese per discutere i progressi", "ru": "Мы встречаемся каждый месяц, чтобы обсудить прогресс", "zh": "我们每月开会讨论进展", "tr": "İlerlemeyi görüşmek için her ay buluşuruz"}),
    ItemCard(english: "She rarely goes out at night.", translations: {"ar": "هي نادراً ما بتخرج بالليل", "de": "Sie geht selten nachts aus", "es": "Ella rara vez sale por la noche", "fr": "Elle sort rarement la nuit", "it": "Lei esce raramente di notte", "ru": "Она редко выходит ночью", "zh": "她很少晚上出去", "tr": "Nadiren gece dışarı çıkar"}),
    ItemCard(english: "I woke up at dawn to pray.", translations: {"ar": "أنا صحيت الفجر عشان أصلي", "de": "Ich wachte im Morgengrauen auf, um zu beten", "es": "Me desperté al amanecer para rezar", "fr": "Je me suis réveillé à l'aube pour prier", "it": "Mi sono svegliato all'alba per pregare", "ru": "Я проснулся на рассвете, чтобы помолиться", "zh": "我在黎明时醒来祈祷", "tr": "Dua etmek için şafakta uyandım"}),
    ItemCard(english: "The store closes at sunset.", translations: {"ar": "المحل بيقفل عند غروب الشمس", "de": "Der Laden schließt bei Sonnenuntergang", "es": "La tienda cierra al atardecer", "fr": "Le magasin ferme au coucher du soleil", "it": "Il negozio chiude al tramonto", "ru": "Магазин закрывается на закате", "zh": "商店在日落时关门", "tr": "Dükkan gün batımında kapanır"}),
    ItemCard(english: "I will be there in a moment.", translations: {"ar": "أنا هستناك هناك في لحظة", "de": "Ich bin gleich da", "es": "Estaré allí en un momento", "fr": "Je serai là dans un instant", "it": "Sarò lì in un momento", "ru": "Я буду там через минуту", "zh": "我马上就到", "tr": "Bir an içinde orada olacağım"}),
    ItemCard(english: "We have known each other for years.", translations: {"ar": "احنا عارفين بعض من سنين", "de": "Wir kennen uns seit Jahren", "es": "Nos conocemos desde hace años", "fr": "Nous nous connaissons depuis des années", "it": "Ci conosciamo da anni", "ru": "Мы знаем друг друга много лет", "zh": "我们认识多年了", "tr": "Yıllardır birbirimizi tanıyoruz"}),
    ItemCard(english: "He always arrives on time.", translations: {"ar": "هو دايماً بيوصل في المعاد", "de": "Er kommt immer pünktlich", "es": "Siempre llega a tiempo", "fr": "Il arrive toujours à l'heure", "it": "Arriva sempre in orario", "ru": "Он всегда приходит вовремя", "zh": "他总是准时到达", "tr": "Her zaman zamanında gelir"}),
  ];

