    ItemCard(english: "The exercise ball helps with core strength.", translations: {"ar": "كرة التمرين بتساعد في تقوية الجذع", "de": "Der Gymnastikball hilft bei der Rumpfkraft", "es": "La pelota de ejercicio ayuda con la fuerza del core", "fr": "Le ballon d'exercice aide à renforcer les abdominaux", "it": "La palla da ginnastica aiuta con la forza del core", "ru": "Фитбол помогает укрепить мышцы кора", "zh": "健身球有助于核心力量", "tr": "Egzersiz topu çekirdek gücüne yardımcı olur"}),
    ItemCard(english: "He needs to improve his stamina and endurance.", translations: {"ar": "هو محتاج يحسن قدرته على التحمل", "de": "Er muss seine Ausdauer verbessern", "es": "Necesita mejorar su resistencia y aguante", "fr": "Il doit améliorer son endurance", "it": "Ha bisogno di migliorare la sua resistenza", "ru": "Ему нужно улучшить выносливость", "zh": "他需要提高耐力和持久力", "tr": "Dayanıklılığını geliştirmesi gerekiyor"}),
    ItemCard(english: "The kettlebell swing is an excellent full-body exercise.", translations: {"ar": "تمرين تأرجح الجرس ممتاز للجسم بالكامل", "de": "Der Kettlebell-Schwung ist eine ausgezeichnete Ganzkörperübung", "es": "El balanceo de pesa rusa es un excelente ejercicio de cuerpo completo", "fr": "Le swing de kettlebell est un excellent exercice pour tout le corps", "it": "Lo swing con kettlebell è un eccellente esercizio per tutto il corpo", "ru": "Махи гирей - отличное упражнение для всего тела", "zh": "壶铃摆动是一项极好的全身运动", "tr": "Kettlebell sallama mükemmel bir tam vücut egzersizidir"}),
    ItemCard(english: "She bought a new exercise mat for her yoga practice.", translations: {"ar": "هي إشتريت سجادة تمرين جديدة لتمارين اليوجا", "de": "Sie kaufte eine neue Trainingsmatte für ihre Yoga-Praxis", "es": "Compró una nueva estera de ejercicio para su práctica de yoga", "fr": "Elle a acheté un nouveau tapis d'exercice pour sa pratique du yoga", "it": "Ha comprato un nuovo tappetino da ginnastica per la sua pratica yoga", "ru": "Купила новый коврик для занятий йогой", "zh": "她为瑜伽练习买了一个新的瑜伽垫", "tr": "Yoga pratiği için yeni bir egzersiz matı aldı"}),
    ItemCard(english: "Consistency is the key to seeing results.", translations: {"ar": "الإستمرارية هي المفتاح لرؤية النتائج", "de": "Beständigkeit ist der Schlüssel zum Erfolg", "es": "La constancia es la clave para ver resultados", "fr": "La constance est la clé pour voir des résultats", "it": "La costanza è la chiave per vedere i risultati", "ru": "Последовательность - ключ к достижению результатов", "zh": "坚持是看到结果的关键", "tr": "Tutarlılık, sonuçları görmenin anahtarıdır"}),
    ItemCard(english: "He uses resistance bands for his shoulder rehab.", translations: {"ar": "هو بيستخدم أربطة مقاومة لإعادة تأهيل كتفه", "de": "Er benutzt Widerstandsbänder für seine Schulterrehabilitation", "es": "Usa bandas de resistencia para la rehabilitación de su hombro", "fr": "Il utilise des bandes de résistance pour la rééducation de son épaule", "it": "Usa fasce elastiche per la riabilitazione della spalla", "ru": "Использует эспандеры для реабилитации плеча", "zh": "他用阻力带进行肩部康复", "tr": "Omuz rehabilitasyonu için direnç bantları kullanıyor"}),
    ItemCard(english: "The leg press machine targets your quads and glutes.", translations: {"ar": "جهاز ضغط القدمين بيستهدف عضلات الفخذ والأرداف", "de": "Die Beinpresse trainiert deine Oberschenkel und Gesäßmuskeln", "es": "La máquina de prensa de piernas trabaja tus cuádriceps y glúteos", "fr": "La machine à presse pour jambes cible vos quadriceps et vos fessiers", "it": "La macchina per leg press mira ai tuoi quadricipiti e glutei", "ru": "Тренажер для жима ногами прорабатывает квадрицепсы и ягодицы", "zh": "腿部推举机针对你的股四头肌和臀肌", "tr": "Leg press makinesi kuadriseps ve glute kaslarını hedefler"}),
    ItemCard(english: "Jump rope is a great calorie burner.", translations: {"ar": "حبل القفز ممتاز لحرق السعرات", "de": "Springseil ist ein großartiger Kalorienverbrenner", "es": "La cuerda para saltar es un excelente quemador de calorías", "fr": "La corde à sauter est un excellent brûleur de calories", "it": "La corda per saltare è un ottimo brucia calorie", "ru": "Скакалка отлично сжигает калории", "zh": "跳绳是很好的卡路里燃烧器", "tr": "Atlama ipi harika bir kalori yakıcıdır"}),
